import{_ as t,o,c as i,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.10.10 — View AI Credit Price List","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/09-admin-functions/3-10-10-view-ai-credit-price-list/spec.md","filePath":"feature/srs/09-admin-functions/3-10-10-view-ai-credit-price-list/spec.md"}'),r={name:"feature/srs/09-admin-functions/3-10-10-view-ai-credit-price-list/spec.md"};function d(c,e,n,s,l,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-10-10-—-view-ai-credit-price-list" tabindex="-1">FR 3.10.10 — View AI Credit Price List <a class="header-anchor" href="#fr-3-10-10-—-view-ai-credit-price-list" aria-label="Permalink to &quot;FR 3.10.10 — View AI Credit Price List&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.10.10</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-137</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View AI Credit Price List</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Admin Functions (<code>3.10</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-30, BR-65</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG03, MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates read-catalog contract from <code>member-credit</code>, <code>workspace-credit-unification</code>, &amp; <code>credit-price-csv-import</code>)</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Display the authoritative AI Credit Operation Price Catalog (<code>GET /api/v1/credit/prices</code>) backed by immutable versioned rows in PostgreSQL <code>ai_credit_operation_prices</code>, clearly distinguishing billable operations (<code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code>), free operations (<code>FREE_V1</code> — <code>0</code> credits), <code>enabled</code> status, billing unit (<code>per request</code> vs <code>per image/video</code>), and current <code>revision</code> for <code>Admin</code> (<code>/admin/credit-prices</code>) and <code>Owner</code> (<code>/agency/:agencyId/credit</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Owner, Admin</code>, I want to execute <strong>View AI Credit Price List</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-30, BR-65</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Owner, Admin</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Transparent Missing vs Disabled vs Free States (<code>BR-65</code>):</strong> Unconfigured operations explicitly show <code>unconfigured</code> (blocking paid dispatch rather than silently charging <code>0</code>); explicit <code>unitCredits = 0</code> with <code>enabled = true</code> shows <code>Free</code>; <code>enabled = false</code> shows <code>Disabled</code>.</li><li><strong>2. Feature-Wide Flat Unit Pricing:</strong> Each image/video/content operation uses one fixed unit-credit price across all supported aspect ratios (<code>4:5</code>, <code>9:16</code>, <code>16:9</code>, <code>1:1</code>) — dimension changes never add hidden surcharges.</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>credit.catalog.*</code>, <code>credit.unit.*</code>, <code>credit.operation.*</code>, <code>credit.csv.featurePricing</code> in <code>src/i18n/locales/{vi,en}/credit.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>pages/credit/prices.tsx</code> (<code>CreditPriceKpiRow.tsx</code>, <code>CreditCatalog.tsx</code>), <code>pages/credit/index.tsx</code> (read-only catalog card for <code>Owner</code>) on Web and <code>src/screens/admin/AdminCreditPricesScreen.tsx</code>, <code>src/screens/billing/AgencyCreditScreen.tsx</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/credit/prices.tsx</code> (<code>CreditPriceKpiRow.tsx</code>, <code>CreditCatalog.tsx</code>), <code>pages/credit/index.tsx</code> (read-only catalog card for <code>Owner</code>)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/admin/AdminCreditPricesScreen.tsx</code>, <code>src/screens/billing/AgencyCreditScreen.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/credit/prices</code></td><td style="text-align:left;">Bearer (<code>Owner</code>, <code>Admin</code>, authenticated workspace members)</td><td style="text-align:left;"><code>CreditPriceController.prices()</code> -&gt; <code>CreditConfigurationService.prices()</code> latest version per supported operation</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Owner, Admin</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-10-11-update-ai-credit-price/spec.html">FR 3.10.11 — Update AI Credit Price</a> · <a href="./../3-10-12-import-ai-credit-price-csv/spec.html">FR 3.10.12 — Import AI Credit Price CSV</a> · <a href="./../../08-subscription-billing/3-9-4-view-ai-credit-tracking/spec.html">FR 3.9.4 — View AI Credit Tracking</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/09-admin-functions.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const h=t(r,[["render",d]]);export{u as __pageData,h as default};
